    return random.sample(seq, len(seq))

def _shuffled(seq: Sequence[str]) -> list[str]:
    from random import seed, shuffle
    if not isinstance(seq, Sequence):
        raise ValueError("Input must be a sequence of strings")
    if not all(isinstance(item, str) for item in seq):
        raise ValueError("All elements in the sequence must be strings")
    seed(len(seq))  # Use the length of the sequence as the seed for deterministic shuffling
    shuffled_list = list(seq)  # Create a copy of the sequence to shuffle
    shuffle(shuffled_list)  # Shuffle the copy
    return shuffled_list

