def normalize_cmd(cmd: tuple[str, ...]) -> tuple[str, ...]:
    # Normalize the command to handle potential issues on Windows
    if isinstance(cmd, tuple):
        cmd = list(cmd)

    # Normalize the paths in the command
    normalized_cmd = [part.replace('\\', '/') for part in cmd]

    return tuple(normalized_cmd)

def normalize_cmd(cmd: tuple[str, ...]) -> tuple[str, ...]:
    if not cmd:
        return ()

    result = []
    for c in cmd:
        if c.startswith('#!'):
            # Normalize shebang to absolute path if possible
            import os
            try:
                abs_path = os.path.abspath(c[2:])
                result.append(f'#!{abs_path}')
            except Exception as e:
                result.append(c)
        else:
            result.append(c)

    return tuple(result)

