    # Checks if the command is empty
    if not cmd:
        return cmd

    # Ensuring the command is a tuple since we are returning a tuple
    if not isinstance(cmd, tuple):
        raise ValueError("Input command must be a tuple")

    # Normalize the command by converting it to a list, join and then convert back to tuple
    normalized_cmd = tuple(" ".join(cmd).split())
    return normalized_cmd

