def ttl_cache(maxsize=128, ttl=600, timer=time.monotonic, typed=False):
    """Decorator to wrap a function with a memoizing callable that saves
    up to `maxsize` results based on a Least Recently Used (LRU)
    algorithm with a per-item time-to-live (TTL) value.
    """

    class TimeTTLCacheLRU:
        def __init__(self, maxsize, ttl, timer, typed):
            self.cache = {}
            self.expiry = {}
            self.maxsize = maxsize
            self.ttl = ttl
            self.timer = timer
            self.typed = typed

        def _is_expired(self, key):
            return self.timer() - self.expiry[key] > self.ttl

        def __call__(self, func):
            @wraps(func)
            def wrapper(*args, **kwargs):
                key = (func, args, tuple(sorted(kwargs.items()))) if self.typed else (func, args, tuple(kwargs.items()))

                if key in self.cache:
                    if not self._is_expired(key):
                        return self.cache[key]

                    del self.cache[key]
                    del self.expiry[key]

                if len(self.cache) >= self.maxsize:
                    oldest_key = None
                    oldest_age = float('inf')
                    for k, age in self.expiry.items():
                        if self._is_expired(k):
                            oldest_key = k
                            break
                        elif age < oldest_age:
                            oldest_key = k
                            oldest_age = age

                    if oldest_key is not None:
                        del self.cache[oldest_key]
                        del self.expiry[oldest_key]
                    else:
                        # All items are still valid, so we need to evict one
                        least_frequently_used_key = min(self.expiry, key=self.expiry.get)
                        del self.cache[least_frequently_used_key]
                        del self.expiry[least_frequently_used_key]

                result = func(*args, **kwargs)
                self.cache[key] = result
                self.expiry[key] = self.timer()
                return result
            return wrapper

    return TimeTTLCacheLRU(maxsize, ttl, timer, typed)

def ttl_cache(maxsize=128, ttl=600, timer=time.monotonic, typed=False):
    def decorator(func):
        cache = {}
        reverse_cache = {}
        next_cleanup = 0

        def cleanup():
            nonlocal cache, reverse_cache, next_cleanup
            current_time = timer()
            to_remove = [key for key, (value, expire) in cache.items() if expire < current_time]
            for key in to_remove:
                del cache[key]
                del reverse_cache[key]
            next_cleanup = current_time + ttl

        def get_key(args, kwargs):
            if typed:
                return (func, args, tuple(kwargs.items()))
            else:
                return (func, tuple(args), tuple(sorted(kwargs.items())))

        def wrapper(*args, **kwargs):
            nonlocal next_cleanup
            current_time = timer()

            if current_time >= next_cleanup:
                cleanup()

            key = get_key(args, kwargs)
            if key in cache and cache[key][1] >= current_time:
                return cache[key][0]

            result = func(*args, **kwargs)
            expire = current_time + ttl
            cache[key] = (result, expire)
            reverse_cache[key] = None  # Value doesn't matter, just used for lookup

            if len(cache) > maxsize:
                cleanup()

            return result

        return wrapper

    return decorator

