    remaining = orderings.copy()

    while remaining:
        new_round = []
        for ordering in remaining:
            if not set(ordering).issubset(visited):
                new_round.append(ordering)
        remaining = new_round

        if not remaining:
            break

        current_ordering = remaining.pop()
        start_index = 0
        for i, item in enumerate(current_ordering):
            if item in visited:
                start_index = i
                break
        merged.extend(current_ordering[start_index:])
        visited.update(current_ordering)

    return merged

