def _c_optimizations_available():
    """
    Return the C optimization module, if available, otherwise
    a false value.

    If the optimizations are required but not available, this
    raises the ImportError.

    This does not say whether they should be used or not.
    """
    try:
        # Attempt to load the C optimization module
        if sys.platform.startswith('win'):
            module = ctypes.cdll.LoadLibrary("c_optimizations.dll")
        elif sys.platform.startswith('linux') or sys.platform.startswith('darwin'):
            module = ctypes.cdll.LoadLibrary("libc_optimizations.so")
        else:
            raise ImportError("Unsupported platform for C optimizations")

        return module
    except OSError as e:
        # If the module is not found, return None
        if "No such file or directory" in str(e):
            return None
        # If the module is not a valid shared object file, raise ImportError
        elif "ldd" in str(e):
            raise ImportError("Failed to load C optimization module")
        else:
            raise ImportError("Unexpected error loading C optimization module: " + str(e))

def _should_attempt_c_optimizations():
    """
    Return a true value if we should attempt to use the C optimizations.

    This takes into account whether we're on PyPy and the value of the
    ``PURE_PYTHON`` environment variable, as defined in `_use_c_impl`.
    """
    if os.environ.get('PURE_PYTHON') == '1':
        return False
    try:
        import sys
        return sys.implementation.name != 'pypy'
    except Exception as e:
        return False

