def reset(self):
    """Reset the histogram.

    Current context is reset to an empty dict.
    Bins are reinitialized with the *initial_value*
    or with *make_bins()* (depending on the initialization).
    """
    self.context = {}
    if hasattr(self, 'initial_value'):
        self.bins = {bin_name: self.initial_value for bin_name in self.bins.keys()}
    elif hasattr(self, 'make_bins'):
        self.bins = self.make_bins()
    else:
        raise AttributeError("Histogram is not properly initialized. Missing 'initial_value' or 'make_bins' attribute.")

