def integral(bins, edges):
    if len(bins) != len(edges) - 1:
        raise ValueError("The length of bins must be one less than the length of edges")

    integral_value = 0.0
    for i in range(len(bins)):
        width = edges[i+1] - edges[i]
        integral_value += bins[i] * width

    return integral_value

def integral(bins, edges):
    """Compute integral (scale for a histogram).

    *bins* contain values, and *edges* form the mesh
    for the integration.
    Their format is defined in :class:`.histogram` description.
    """
    if not bins or not edges:
        raise ValueError("Bins and edges must not be empty.")

    if len(bins) != len(edges) - 1:
        raise ValueError("Length of bins must be one less than the length of edges.")

    if any(b <= 0 for b in bins):
        raise ValueError("All bin values must be positive.")

    if any(e1 >= e2 for e1, e2 in zip(edges, edges[1:])):
        raise ValueError("Edges must be in strictly increasing order.")

    integral_value = 0.0
    for i in range(len(bins)):
        width = edges[i+1] - edges[i]
        integral_value += bins[i] * width

    return integral_value

