def difference(d1, d2, level=-1):
    result = {}
    if level == 0:
        return result

    for k, v1 in d1.items():
        if k not in d2:
            result[k] = copy.deepcopy(v1)
        elif isinstance(v1, dict) and isinstance(d2[k], dict):
            diff = difference(v1, d2[k], level - 1 if level > 0 else level)
            if diff:
                result[k] = diff
        elif v1 != d2[k]:
            result[k] = copy.deepcopy(v1)

    return result

def difference(d1, d2, level=-1, current_level=0):
    if level == 0:
        return {}

    result = {}

    for key in d1:
        if key not in d2:
            result[key] = copy.deepcopy(d1[key])
        else:
            if isinstance(d1[key], dict) and isinstance(d2[key], dict):
                sub_diff = difference(d1[key], d2[key], level, current_level + 1)
                if sub_diff:
                    result[key] = sub_diff
            elif d1[key] != d2[key]:
                result[key] = copy.deepcopy(d1[key])

    return result

def difference(d1, d2, level=-1):
    """Return a dictionary with items from *d1* not contained in *d2*.

    *level* sets the maximum depth of recursion. For infinite recursion,
    set that to -1. For level 1,
    if a key is present both in *d1* and *d2* but has different values,
    it is included into the difference.
    See :func:`intersection` for more details.

    *d1* and *d2* remain unchanged. However, *d1* or some of its
    subdictionaries may be returned directly.
    Make a deep copy of the result when appropriate.

    .. versionadded:: 0.5
       add keyword argument *level*.
    """
    if not isinstance(d1, dict) or not isinstance(d2, dict):
        raise ValueError("Both inputs must be dictionaries")

    if level == 0:
        return {}

    result = {}
    for key, value in d1.items():
        if key not in d2:
            result[key] = copy.deepcopy(value)
        elif isinstance(value, dict) and isinstance(d2[key], dict) and level != 1:
            diff = difference(value, d2[key], level - 1)
            if diff:
                result[key] = diff
        elif value != d2[key]:
            result[key] = copy.deepcopy(value)

    return result

def difference(d1, d2, level=-1, current_level=0):
    if not isinstance(d1, dict) or not isinstance(d2, dict):
        return d1
    result = {}
    keys = set(d1.keys()).union(d2.keys())
    for key in keys:
        if key not in d2:
            result[key] = d1[key]
        elif level == -1 or current_level < level:
            sub_diff = difference(d1[key], d2[key], level, current_level + 1)
            if sub_diff:
                result[key] = sub_diff
    return result

def difference(d1, d2, level=-1):
