    Coordinates outside the histogram edges are ignored.
    """
    if hasattr(self, 'edges'):
        lower_edge = self.edges[0]
        upper_edge = self.edges[-1]
        if lower_edge <= coord <= upper_edge:
            bin_index = self._get_bin_index(coord)
            if bin_index is not None:
                self._bins[bin_index] += weight
        else:
            pass
    else:
        raise ValueError("Histogram edges not defined")

def fill(self, coord, weight=1):
    """Fill histogram at *coord* with the given *weight*.

    Coordinates outside the histogram edges are ignored.
    """
    if coord < self.low or coord > self.high:
        return
    index = self._find_index(coord)
    if index is not None:
        self.bins[index] += weight

def _validate_labels(labels):
    """Check that keys and values in the given labels match against their corresponding
    regular expressions.

    Args:
        labels (dict): the different labels to validate.

    Raises:
        ValidationError: if any of the keys and labels does not match their respective
            regular expression. The error contains as message the list of all errors
            which occurred in the labels. Each element of the list is a dictionary with
            one key-value pair:
            - key: the label key or label value for which an error occurred as string.
            - value: the error message.
    """
    import re
    key_regex = re.compile(r'^[a-zA-Z0-9._-]+$')
    value_regex = re.compile(r'^[a-zA-Z0-9._-]+$')

    errors = []
    for key, value in labels.items():
        if not isinstance(key, str):
            errors.append({"key": key, "value": "Expected string for key"})
            continue
        if not key_regex.match(key):
            errors.append({"key": key, "value": f"Label key '{key}' does not match the regex"})

        if isinstance(value, list):
            for item in value:
                if not isinstance(item, str):
                    errors.append({"key": item, "value": "Expected string or bytes-like object"})
                elif not value_regex.match(item):
                    errors.append({"key": item, "value": "Value does not match the regex"})
        elif not isinstance(value, str):
            errors.append({"key": value, "value": "Expected string or bytes-like object"})
        elif not value_regex.match(value):
            errors.append({"key": value, "value": "Value does not match the regex"})

    if errors:
        raise ValidationError(errors)

