def update_last_applied_manifest_list_from_resp(last_applied_manifest, observer_schema, response):
    if not all(isinstance(item, list) for item in [last_applied_manifest, observer_schema, response]):
        raise ValueError("All inputs must be of type list")

    for item in observer_schema:
        if not isinstance(item, dict):
            raise ValueError("Items in observer_schema must be dictionaries")
        key = next(iter(item.keys()))
        if key not in response or not all(isinstance(sub_item, dict) for sub_item in response[key]):
            continue

        for sub_item in response[key]:
            if not isinstance(sub_item, dict):
                continue
            sub_key = next(iter(sub_item.keys()))
            if sub_key not in last_applied_manifest:
                last_applied_manifest.append({sub_key: sub_item[sub_key]})
            else:
                last_applied_manifest[last_applied_manifest.index({sub_key: last_applied_manifest[sub_key]})][sub_key] = sub_item[sub_key]

    return last_applied_manifest

def update_last_applied_manifest_dict_from_resp(last_applied_manifest, observer_schema, response):
    for field, value in observer_schema.items():
        if field in response:
            if isinstance(value, dict):
                update_last_applied_manifest_dict_from_resp(last_applied_manifest.get(field, {}), value, response[field])
            else:
                last_applied_manifest[field] = response[field]
        elif field not in last_applied_manifest:
            raise KeyError(f"Observed field '{field}' not present in Kubernetes response")
    return last_applied_manifest

def generate_default_observer_schema(app):
    # Initialize a dictionary to store the default observer schemas for each Kubernetes resource
    default_schemas = {}

    # Iterate through each resource in the application's manifest
    for resource in app.manifest.get("resources", []):
        # Extract the resource kind and group
        kind = resource.get("kind")
        apiGroup = resource.get("apiVersion", "").split("/")[0]

        # Generate the default observer schema for the resource
        default_schema = {
            "kind": kind,
            "apiVersion": apiGroup,
            "metadata": {
                "name": "{{ .metadata.name }}"
            },
            "spec": {
                # Add default spec fields based on the resource kind
                "field1": "{{ .spec.field1 }}",
                "field2": "{{ .spec.field2 }}"
            }
        }

        # Store the default schema for the resource
        default_schemas[f"{apiGroup}/{kind}"] = default_schema

    return default_schemas

