		self,
		sql: AnyStr,
		params: Union[Dict[Union[str, int], Any], Sequence[Any]],
	) -> Tuple[AnyStr, Union[Dict[Union[str, int], Any], Sequence[Any]]]:
		if isinstance(sql, str):
			sql_out = sql
		else:
			sql_out = sql.decode('utf-8')

		if isinstance(params, dict):
			params_out = []
			for key, value in params.items():
				params_out.append(value)
		elif isinstance(params, list):
			params_out = params
		else:
		 raise ValueError("params must be a dict or a sequence")

		return sql_out, params_out

def format(sql: AnyStr, params: Union[Dict[Union[str, int], Any], Sequence[Any]]) -> Tuple[AnyStr, Union[Dict[Union[str, int], Any], Sequence[Any]]]:
    if not isinstance(sql, (str, bytes)):
        raise TypeError("sql must be a str or bytes")

    if not isinstance(params, (dict, Sequence)):
        raise TypeError("params must be a dict or Sequence")

    if isinstance(sql, bytes) and not isinstance(params, Sequence):
        raise TypeError("if sql is bytes, params must be a Sequence")

    if isinstance(sql, str) and not isinstance(params, dict):
        raise TypeError("if sql is str, params must be a dict")

    if isinstance(params, dict):
        out_style_params = {f"${k}": v for k, v in params.items()}
    else:
        out_style_params = [f"${i+1}" for i in range(len(params))]

    formatted_sql = sql.format(*params) if isinstance(params, Sequence) else sql.format(**params)

    return formatted_sql, out_style_params

