def validate(self, path):
    """Validate OCFL object at path or pyfs root.

    Returns True if valid (warnings permitted), False otherwise.
    """
    try:
        if not os.path.isdir(path):
            return False

        root_level_dir = os.listdir(path)
        if len(root_level_dir) != 3 or 'data' not in root_level_dir or 'manifest.json' not in root_level_dir or 'inventory.json' not in root_level_dir:
            return False

        manifest_path = os.path.join(path, 'manifest.json')
        with open(manifest_path, 'r') as f:
            manifest = json.load(f)
            if not isinstance(manifest, dict) or 'objects' not in manifest:
                return False

            for obj_id, obj_info in manifest['objects'].items():
                if not isinstance(obj_id, str) or not isinstance(obj_info, dict):
                    return False

                object_path = os.path.join(path, obj_id)
                if not os.path.isdir(object_path):
                    return False

                versions_path = os.path.join(object_path, 'versions')
                if not os.path.isdir(versions_path):
                    return False

                version_dir_list = os.listdir(versions_path)
                for version_dir in version_dir_list:
                    version_path = os.path.join(versions_path, version_dir)
                    if not os.path.isdir(version_path):
                        return False

                    inventory_path = os.path.join(version_path, 'inventory.json')
                    with open(inventory_path, 'r') as f:
                        inventory = json.load(f)
                        if not isinstance(inventory, dict) or 'manifest' not in inventory:
                            return False

                        for file_path, file_info in inventory['manifest'].items():
                            if not isinstance(file_path, str) or not isinstance(file_info, dict):
                                return False

                            file_hash = os.path.join(version_path, file_info['location'])
                            if not os.path.isfile(file_hash):
                                return False

                            with open(file_hash, 'rb') as f:
                                file_data = f.read()
                                if file_info['hash'] != hashlib.sha256(file_data).hexdigest():
                                    return False

        return True
    except Exception as e:
        print(f"Validation error: {e}")
        return False

def validate(self, path):
    import os

    if not os.path.exists(path):
        raise FileNotFoundError(f"The path '{path}' does not exist.")

    try:
        # Check if the path is a directory
        if not os.path.isdir(path):
            raise NotADirectoryError(f"The path '{path}' is not a directory.")

        # Check for the presence of an "ocfl_version" file
        ocfl_version_path = os.path.join(path, ".ocfl_version")
        if not os.path.exists(ocfl_version_path):
            raise FileNotFoundError(f"The OCFL object is missing the '.ocfl_version' file.")

        # Read the content of the ".ocfl_version" file
        with open(ocfl_version_path, 'r') as file:
            ocfl_version = file.read().strip()
            if not ocfl_version:
                raise ValueError(f"The '.ocfl_version' file is empty.")

        # Check if the ocfl_version is in a valid format
        # Example: 'OCFL_1_0'
        if not ocfl_version.startswith('OCFL_'):
            raise ValueError(f"The '.ocfl_version' file contains an invalid version: {ocfl_version}")

    except Exception as e:
        print(f"Validation failed: {e}")
        return False

    return True

def validate(self, path):
    """Validate OCFL object at path or pyfs root.

    Returns True if valid (warnings permitted), False otherwise.
    """
    if not os.path.exists(path):
        return False

    if not os.path.isdir(path):
        return False

    if not os.listdir(path):
        return False

    for root, dirs, files in os.walk(path):
        if '.ocfl_root.txt' not in files:
            return False
        if not all(f.endswith('.ocfl_inventory') for f in files):
            return False
        for dir in dirs:
            if 'digest' in dir:
                if not all(f.endswith('.ocfl_inventory') for f in os.listdir(os.path.join(root, dir))):
                    return False

    return True

