def check_digests_present_and_used(self, manifest_files, digests_used):
    """Check all digests in manifest that are needed are present and used."""
    if not manifest_files:
        raise ValueError("Manifest files list cannot be empty")
    if not digests_used:
        return True  # No need to check if no digests are used

    needed_digests = set()
    for manifest_file in manifest_files:
        try:
            with open(manifest_file, 'r') as file:
                for line in file:
                    digest = line.strip()
                    if digest:
                        needed_digests.add(digest)
        except FileNotFoundError:
            print(f"Manifest file not found: {manifest_file}")
            return False
        except Exception as e:
            print(f"Error reading manifest file {manifest_file}: {e}")
            return False

    missing_digests = needed_digests - digests_used
    if missing_digests:
        print(f"Missing digests: {', '.join(missing_digests)}")
        return False

    unused_digests = digests_used - needed_digests
    if unused_digests:
        print(f"Unused digests: {', '.join(unused_digests)}")
        return False

    return True

def check_digests_present_and_used(self, manifest_files, digests_used):
