def get_logical_path_map(inventory, version):
    """
    Get a map of logical paths in state to files on disk for version in inventory.

    Returns:
        dict: logical_path_in_state -> set(content_files)

    Raises:
        ValueError: If the version is not found in the inventory.
        TypeError: If the inventory is not a dictionary or the version is not a string.
    """
    if not isinstance(inventory, dict):
        raise TypeError("Inventory must be a dictionary")
    if not isinstance(version, str):
        raise TypeError("Version must be a string")

    if version not in inventory:
        raise ValueError(f"Version {version} not found in inventory")

    logical_path_map = {}
    for logical_path, files in inventory[version].items():
        if isinstance(files, list):
            logical_path_map[logical_path] = set(files)
        else:
            logical_path_map[logical_path] = {files}

    return logical_path_map

