def _explore_zipfile(zip_path):
    """
    Get packages' data from zip_path

    Groups files by their XML basename and returns data in dict format.

    Parameters
    ----------
    zip_path : str
        zip file path
    Returns
    -------
    dict
    """
    if not os.path.isfile(zip_path) or not zip_path.endswith('.zip'):
        raise ValueError("Invalid zip file path")

    file_dict = {}
    try:
        with zipfile.ZipFile(zip_path, 'r') as zip:
            for file_info in zip.infolist():
                if file_info.filename.endswith('.xml'):
                    basename = os.path.splitext(file_info.filename)[0]
                    file_data = zip.read(file_info.filename)
                    if basename in file_dict:
                        file_dict[basename].append(file_data)
                    else:
                        file_dict[basename] = [file_data]
    except Exception as e:
        raise RuntimeError(f"Error exploring zipfile: {e}")

    return file_dict

