def _extract_number_and_supplment_from_issue_element(issue):
    issue = issue.strip()
    if not issue.startswith("<issue>") or not issue.endswith("</issue>"):
        raise ValueError("Input is not in the correct format <issue>xxxx</issue>")

    issue_text = issue[7:-8].strip()
    parts = issue_text.split()

    for part in parts:
        if part.isdigit():
            number = int(part)
        elif part.lower().startswith("suppl"):
            suppl = part.replace("suppl", "", 1).strip().replace ".", "").strip()
        elif part.lower() in ["spe", "supl"]:
            suppl = part

    return number, suppl if suppl else None

def _extract_number_and_supplment_from_issue_element(issue):
    pattern = re.compile(r'(\d+)\s*(Suppl|suppl|spe|Suppl\.?\d|Suppl\s+\d|Suppl.\s*\d|Supp\s+\d)\s*(\d+)?')
    match = pattern.search(issue)

    if match:
        number = match.group(1)
        suppl = match.group(3) if match.group(3) else match.group(2)
        return number, suppl
    else:
        raise ValueError("Invalid issue format")

