                    return expr[0]
            elif len(expr) == 4 and expr[1] == '&' and expr[2] == '|':
                if expr[0] == expr[3]:
                    return expr[0]
            elif len(expr) == 4 and expr[1] == '|' and expr[2] == '&':
                if expr[0] == expr[3]:
                    return expr[0]
        return expr

    result = [apply_absorption(arg) for arg in args]
    return result

