                return expr.right  # A & (~A | B) = A & B
            elif expr.left.type == 'And' and expr.left.right.type == 'Not' and expr.left.right.expr == expr.right:
                return expr.left.left  # A & (~A & B) = A & B
        elif expr.type == 'Or':
            if expr.left.type == 'Or' and expr.left.left.type == 'Not' and expr.left.left.expr == expr.right:
                return expr.right  # A | (~A | B) = A | B
            elif expr.left.type == 'And' and expr.left.right.type == 'Not' and expr.left.right.expr == expr.right:
                return expr.left.left  # A | (~A & B) = A | B
