def next_version(version):
    try:
        # Split version into parts and convert each part to integer
        parts = [int(part) for part in version.split('.')]

        # Find the last non-zero part to increment
        for i in range(len(parts) - 1, -1, -1):
            if parts[i] > 0:
                parts[i] += 1
                # Reset parts to the right to zero
                for j in range(i + 1, len(parts)):
                    parts[j] = 0
                break
        else:
            # If all parts were zero, increment the most significant part
            parts = [1] + parts

        # Join the parts back into a version string
        return '.'.join(map(str, parts))
    except (AttributeError, ValueError):
        # Handle invalid input gracefully
        return "Invalid version format"

def next_version(version):
    """Next version identifier following existing pattern.

    Must deal with both zero-prefixed and non-zero prefixed versions.
    """

    def parse_version(version):
        parts = version.split('.')
        return [int(part) for part in parts]

    def increment_version(version_parts):
        if not version_parts:
            return [1]
        if version_parts[-1] < 9:
            version_parts[-1] += 1
        else:
            version_parts[-1] = 0
            version_parts = increment_version(version_parts[:-1])
        return version_parts

    try:
        version_parts = parse_version(version)
        next_parts = increment_version(version_parts)
        next_version = '.'.join(str(part) for part in next_parts)
        return next_version
    except ValueError as e:
        print(f"Error parsing version: {e}")
        return None

