def bash_completion():
    """
    Return a bash completion script for the borgmatic command. Produce this by introspecting
    borgmatic's command-line argument parsers.
    """
    # Step 1: Import necessary libraries
    import argparse
    import sys

    # Step 2: Define a function to generate bash completion for a given parser
    def generate_bash_completion(parser):
        completion = []
        for action in parser._actions:
            if action.nargs == 0:
                completion.append(f"\"{action.option_strings[0]}\"")
            else:
                completion.append(f"\"{action.option_strings[0]}\": completion_words")
        return " ".join(completion)

    # Step 3: Define a function to get the main parser
    def get_main_parser():
        import borgmatic
        return borgmatic.cli.parsers.main()

    # Step 4: Generate bash completion script
    parser = get_main_parser()
    completion_script = f'complete -W "{generate_bash_completion(parser)}" borgmatic'

    return completion_script

def parse_arguments(*unparsed_arguments):
    subparser_names = set()
    parser = argparse.ArgumentParser(add_help=False)
    subparsers = parser.add_subparsers(dest='subparser_name')

    # Define subparsers (example: 'foo' and 'bar')
    foo_parser = subparsers.add_parser('foo')
    foo_parser.add_argument('--foo-arg', help='Argument for foo')

    bar_parser = subparsers.add_parser('bar')
    bar_parser.add_argument('--bar-arg', help='Argument for bar')

    # Parse arguments
    arguments = {}
    for arg_group in unparsed_arguments:
        parsed_args, unknown_args = parser.parse_known_args(arg_group.split())
        if parsed_args.subparser_name:
            subparser_names.add(parsed_args.subparser_name)
            if parsed_args.subparser_name not in arguments:
                arguments[parsed_args.subparser_name] = parser.parse_args(arg_group.split())
        else:
            arguments['global'] = parser.parse_args(arg_group.split())

    # Handle unknown arguments
    for subparser_name in subparser_names:
        if subparser_name in arguments and getattr(arguments[subparser_name], '_unknown', None):
            unknown_args = getattr(arguments[subparser_name], '_unknown')
            arguments[subparser_name] = parser.parse_args([subparser_name] + unknown_args)

    return arguments

def parse_subparser_arguments(unparsed_arguments, subparsers):
    """
    Given a sequence of arguments and a dict from subparser name to argparse.ArgumentParser
    instance, give each requested action's subparser a shot at parsing all arguments. This allows
    common arguments like "--repository" to be shared across multiple subparsers.

    Return the result as a tuple of (a dict mapping from subparser name to a parsed namespace of
    arguments, a list of remaining arguments not claimed by any subparser).
    """
    parsed_arguments = {}
    remaining_arguments = list(unparsed_arguments)

    for subparser_name, parser in subparsers.items():
        subparser_args = [arg for arg in remaining_arguments if not arg.startswith('-')]
        if subparser_args:
            try:
                namespace, unrecognized = parser.parse_known_args(subparser_args)
                parsed_arguments[subparser_name] = namespace
                remaining_arguments = [arg for arg in remaining_arguments if arg not in subparser_args + list(unrecognized)]
            except SystemExit:
                # argparse raises SystemExit if the arguments are invalid
                pass

    return parsed_arguments, remaining_arguments

