def int_to_string(number: int, alphabet: List[str], padding: Optional[int] = None) -> str:
    if not 0 <= number < len(alphabet):
        raise ValueError("Number is out of the valid range for the given alphabet")

    result = ""
    while number > 0:
        number, remainder = divmod(number, len(alphabet))
        result = alphabet[remainder] + result

    if padding is not None:
        result = result.zfill(padding)

    return result

def int_to_string(number: int, alphabet: List[str], padding: Optional[int] = None) -> str:
    if not alphabet or not all(isinstance(char, str) for char in alphabet):
        raise ValueError("Invalid alphabet provided")
    if padding is not None and (not isinstance(padding, int) or padding < 0):
        raise ValueError("Invalid padding provided")
    if number < 0:
        raise ValueError("Negative numbers are not supported")

    if number == 0:
        return alphabet[0] if padding is None or padding == 0 else alphabet[0] * padding

    digits = []
    while number > 0:
        digits.append(alphabet[number % len(alphabet)])
        number //= len(alphabet)

    if padding is not None and padding > len(digits):
        digits.extend([alphabet[0]] * (padding - len(digits)))

    return ''.join(digits[::-1])

def int_to_string(number: int, alphabet: List[str], padding: Optional[int] = None) -> str:
    if not alphabet or not all(isinstance(char, str) for char in alphabet):
        raise ValueError("Alphabet must be a list of strings")
    if padding is not None and not isinstance(padding, int) or padding < 0:
        raise ValueError("Padding must be a non-negative integer or None")

    if number == 0:
        return alphabet[0]

    digits = []
    base = len(alphabet)

    while number > 0:
        remainder = number % base
        digits.append(alphabet[remainder])
        number //= base

    if padding is not None and len(digits) < padding:
        digits.extend([alphabet[0]] * (padding - len(digits)))

    result = ''.join(reversed(digits))
    return result

