    if padding is not None and (padding < 0 or padding < len(number)):
        raise ValueError("Padding must be non-negative and at least as long as the number")

    result = []
    while number > 0:
        number, remainder = divmod(number, len(alphabet))
        result.append(alphabet[remainder])

    result = ''.join(reversed(result))

    if padding is not None:
