def int_to_string(number: int, alphabet: List[str], padding: Optional[int] = None) -> str:
    if not alphabet:
        raise ValueError("Alphabet cannot be empty")
    if padding is not None and padding < 0:
        raise ValueError("Padding cannot be negative")

    digits = []

    # Convert number to base of alphabet length
    base = len(alphabet)
    while number > 0:
        digits.append(alphabet[number % base])
        number //= base

    # Reverse the digits to get the most significant digit first
    result = ''.join(digits[::-1])

    # Pad with leading zeros if necessary
    if padding is not None:
        if len(result) > padding:
            raise ValueError("Number is too large for given padding")
        padding = padding - len(result)
        result = '0' * padding + result

    return result

