    '''
    name, default = matcher.split('=', 1) if '=' in matcher else (matcher, None)
    name = name.strip()
    default = default.strip() if default else None

    if name in os.environ:
        return os.environ[name].strip()
    elif default:
        return default
    else:
        raise ValueError(f"Environment variable '{name}' is not set and no default value provided.")

def _parse_image_ref(image_href: str) -> Tuple[str, str, bool]:
    """Parse an image href into composite parts.

    :param image_href: href of an image
    :returns: a tuple of the form (image_id, netloc, use_ssl)
    :raises ValueError: if the href is not a valid URL

    """
    try:
        parsed_url = urllib.parse.urlparse(image_href)
        if not parsed_url.netloc:
            raise ValueError("No network location specified in the URL")
        if parsed_url.scheme not in ["http", "https"]:
            raise ValueError("Unsupported URL scheme")
        use_ssl = parsed_url.scheme == "https"
        image_id = parsed_url.path.strip('/')
        netloc = parsed_url.netloc
        return image_id, netloc, use_ssl
    except ValueError as e:
        raise ValueError(f"Invalid URL: {image_href}") from e
    except Exception as e:
        raise ValueError(f"An error occurred while parsing the URL: {e}")

