def find_roots(graph: Graph, prop: URIRef, roots: Optional[Set[Node]] = None) -> Set[Node]:
    if roots is None:
        roots = set()

    children = set(graph.subjects(predicate=prop, object=None))

    for child in children:
        parents = list(graph.objects(subject=child, predicate=prop))
        if not parents:
            roots.add(child)
        else:
            for parent in parents:
                if parent not in roots:
                    roots.add(parent)

    return roots

