def gaussian(x):
    """
    Gaussian centered around 0.2 with a sigma of 0.1.
    """
    return (1 / (np.sqrt(2 * np.pi) * 0.1)) * np.exp(-(x - 0.2) ** 2 / (2 * 0.1 ** 2))

def load_configurations(config_filenames: List[str], overrides: Dict[str, str] = None, resolve_env: bool = True) -> Tuple[Dict[str, dict], List[logging.LogRecord]]:
    config_dicts = {}
    parse_errors = []

    for filename in config_filenames:
        try:
            with open(filename, 'r') as file:
                config_json = file.read()
                if resolve_env:
                    config_json = config_json.replace('${', '').replace('}', '')
                config_dict = json.loads(config_json)

                if overrides:
                    config_dict = {**config_dict, **overrides}

                config_dicts[filename] = config_dict
        except FileNotFoundError:
            logging.error(f"Configuration file not found: {filename}")
            parse_errors.append(logging.LogRecord('load_configurations', logging.ERROR, filename, 0, "Configuration file not found: %s", (filename,), None))
        except json.JSONDecodeError:
            logging.error(f"Error decoding JSON from file: {filename}")
            parse_errors.append(logging.LogRecord('load_configurations', logging.ERROR, filename, 0, "Error decoding JSON from file: %s", (filename,), None))
        except Exception as e:
            logging.error(f"Unexpected error while loading configuration file: {filename}: {e}")
            parse_errors.append(logging.LogRecord('load_configurations', logging.ERROR, filename, 0, "Unexpected error while loading configuration file: %s: %s", (filename, str(e)), None))

    return config_dicts, parse_errors

