def load_configurations(config_filenames, overrides=None, resolve_env=True):
    import os
    from configparser import ConfigParser
    from logging import LogRecord

    config_dict = {}
    log_records = []

    if overrides is None:
        overrides = {}

    for filename in config_filenames:
        if not os.path.exists(filename):
            log_records.append(LogRecord(name="ConfigLoader", level=logging.ERROR, msg=f"File not found: {filename}"))
            continue

        parser = ConfigParser()
        try:
            parser.read(filename)
        except Exception as e:
            log_records.append(LogRecord(name="ConfigLoader", level=logging.ERROR, msg=f"Error reading file {filename}: {str(e)}"))
            continue

        parsed_config = {section: {key: value for key, value in parser.items(section)} for section in parser.sections()}
        config_dict[filename] = parsed_config

        for section in parsed_config:
            for key, value in parsed_config[section].items():
                if value.startswith('${') and value.endswith('}'):
                    env_var = value[2:-1]
                    if env_var in os.environ:
                        parsed_config[section][key] = os.environ[env_var]
                    elif resolve_env:
                        log_records.append(LogRecord(name="ConfigLoader", level=logging.WARNING, msg=f"Environment variable not set: {env_var}"))

        config_dict[filename].update(overrides.get(filename, {}))

    return config_dict, log_records

def protocol_handlers(cls, protocol_version=None):
        """ Return a dictionary of available Bolt protocol handlers,
        keyed by version tuple. If an explicit protocol version is
        provided, the dictionary will contain either zero or one items,
        depending on whether that version is supported. If no protocol
        version is provided, all available versions will be returned.

        :param protocol_version: tuple identifying a specific protocol
            version (e.g. (3, 5)) or None
        :return: dictionary of version tuple to handler class for all
            relevant and supported protocol versions
        :raise TypeError: if protocol version is not passed in a tuple
        """
        if protocol_version is not None and not isinstance(protocol_version, tuple):
            raise TypeError("Protocol version must be a tuple")

        handlers = {}
        supported_versions = {(3, 0), (3, 1), (3, 4), (3, 5), (4, 0)}

        if protocol_version is not None:
            if protocol_version in supported_versions:
                handlers[protocol_version] = cls.get_handler_class(protocol_version)
        else:
            for version in supported_versions:
                handlers[version] = cls.get_handler_class(version)

        return handlers

    @staticmethod
    def get_handler_class(version):
        if version == (3, 0):
            return Bolt30Handler
        elif version == (3, 1):
            return Bolt31Handler
        elif version == (3, 4):
            return Bolt34Handler
        elif version == (3, 5):
            return Bolt35Handler
        elif version == (4, 0):
            return Bolt40Handler
        else:
            raise ValueError("Unsupported protocol version")

def protocol_handlers(cls, protocol_version=None):
        available_versions = {
            (3, 4): cls.ProtocolHandler34,
            (3, 5): cls.ProtocolHandler35,
            (4, 0): cls.ProtocolHandler40
        }

        if protocol_version is not None:
            if not isinstance(protocol_version, tuple):
                raise TypeError("protocol version must be passed in a tuple")
            return {protocol_version: available_versions.get(protocol_version, None)}
        else:
            return available_versions

