def _get_seq_with_type(seq, bufsize=None):
    """Return a (sequence, type) pair.
    Sequence is derived from *seq*
    (or is *seq*, if that is of a sequence type).
    """
    if seq is None:
        raise ValueError("Input sequence cannot be None")

    if not (isinstance(seq, (list, tuple, str)) or (bufsize is not None and isinstance(bufsize, int))):
        raise TypeError("Invalid input type. Expected a sequence or int for bufsize.")

    if bufsize is not None and bufsize < 0:
        raise ValueError("bufsize cannot be negative")

    if isinstance(seq, (list, tuple, str)):
        return seq, type(seq)
    else:
        raise TypeError("Unsupported sequence type")

