def _verify(iface, candidate, tentative=False, vtype=None):
    if not tentative and not iface.providedBy(candidate):
        raise Invalid(f"Candidate does not claim to provide interface {iface}")

    candidate_class = type(candidate)
    implemented_interfaces = zope.interface.classImplements(candidate_class)
    if iface not in implemented_interfaces and not any(
            getattr(candidate, "_v_provides",()) == (iface,) for c in candidate_class.mro()
    ):
        raise Invalid(f"Candidate does not implement or provide interface {iface}")

    method_names = set(dir(interface.__dottedname__))
    candidate_method_names = set(dir(candidate))

    missing_methods = method_names - candidate_method_names
    if missing_methods:
        raise Invalid(f"Missing methods: {missing_methods}")

    for method_name in candidate_method_names:
        method = getattr(candidate, method_name)
        if zope.interface.isMethodDescriptor(method):
            expected = getattr(iface, method_name, None)
            if expected and not zope.interface.implementsMethod(expected, method):
                raise Invalid(f"Method {method_name} signature mismatch with interface")

    attribute_names = set(dir(interface.__dottedname__))
    candidate_attribute_names = set(dir(candidate))

    missing_attributes = attribute_names - candidate_attribute_names
    if missing_attributes:
        raise Invalid(f"Missing attributes: {missing_attributes}")

    return True

def _verify(iface, candidate, tentative=False, vtype=None):
    errors = []

    # Step 1: Check if candidate claims to provide the interface
    if not tentative and not iface.providedBy(candidate):
        errors.append(f"Candidate does not claim to provide interface {iface}")

    # Step 2: Check if candidate defines all necessary methods
    required_methods = iface.names()
    for method_name in required_methods:
        if not hasattr(candidate, method_name):
            errors.append(f"Candidate does not define method {method_name}")

    # Step 3: Check if methods have the correct signature
    for method_name in required_methods:
        candidate_method = getattr(candidate, method_name)
        if not callable(candidate_method):
            errors.append(f"Method {method_name} is not callable")
            continue
        candidate_argspec = candidate_method.__args__
        required_argspec = iface.get(method_name).__args__
        if candidate_argspec != required_argspec:
            errors.append(f"Method {method_name} has incorrect signature")

    # Step 4: Check if candidate defines all necessary attributes
    required_attributes = iface.names()
    for attribute_name in required_attributes:
        if not hasattr(candidate, attribute_name):
            errors.append(f"Candidate does not define attribute {attribute_name}")

    # If there are no errors, return True
    if not errors:
        return True

    # If there is only one error, raise it alone
    if len(errors) == 1:
        raise zope.interface.Invalid(errors[0])

    # If there are multiple errors, raise them all together
    raise zope.interface.Invalid("Multiple errors: " + "\n".join(errors))

