    if is_dst:
        fold = (dt - self._target_tz.utcoffset(dt)).utcoffset() is not None
        new_dt = self._adjust_fold(new_dt, fold)

    return new_dt

def fromutc(self, dt):
    if not isinstance(dt, datetime.datetime) or dt.tzinfo is None:
        raise ValueError("Input must be a timezone-aware datetime object")

    try:
        local_dt = dt.astimezone(self.tz)
        if dt <= local_dt:
            return local_dt
        else:
            # Handle the "fold" state where the same UTC time occurs twice due to a timezone change
            return local_dt - datetime.timedelta(hours=1)
    except Exception as e:
        raise RuntimeError(f"Failed to convert datetime to timezone: {e}")

