def find_tags(text: str, replacer: callable = None) -> Tuple[Set, str]:
    tags = set()
    in_code_block = False
    replaced_text = []
    tag_buffer = ""

    for char in text:
        if char == "`":
            in_code_block = not in_code_block
        elif char == "#" and not in_code_block:
            tag_buffer += char
        elif char == " " and not in_code_block:
            if tag_buffer.strip():
                tags.add(tag_buffer.strip())
                tag_buffer = ""
        elif not in_code_block:
            tag_buffer += char
        elif in_code_block:
            replaced_text.append(char)

    if tag_buffer.strip():
        tags.add(tag_buffer.strip())

    if replacer:
        replaced_text = [replacer(tag) if tag in tags else tag for tag in replaced_text]

    return tags, "".join(replaced_text)

