def parse_diaspora_webfinger(document: str) -> Dict:
    """
    Parse Diaspora webfinger which is either in JSON format (new) or XRD (old).

    https://diaspora.github.io/diaspora_federation/discovery/webfinger.html
    """
    try:
        # Check if the document is in JSON format
        try:
            parsed = json.loads(document)
            if isinstance(parsed, dict):
                return parsed
        except json.JSONDecodeError:
            pass

        # If not JSON, try to parse as XRD
        try:
            root = ET.fromstring(document)
            if root.tag != '{http://docs.oasis-open.org/ns/xri/xrd-1.0}XRD':
                raise ValueError("Not a valid XRD document")

            result = {}
            for link in root.findall('{http://docs.oasis-open.org/ns/xri/xrd-1.0}Link'):
                rel = link.get('rel')
                href = link.get('href')
                if rel and href:
                    result[rel] = href

            return result
        except ET.ParseError:
            raise ValueError("Not a valid XRD document")

    except Exception as e:
        raise ValueError(f"Unable to parse webfinger document: {e}")

def parse_diaspora_webfinger(document: str) -> Dict:
    try:
        if document.startswith('{'):
            # JSON format
            return json.loads(document)
        elif document.startswith('<'):
            # XRD format
            tree = fromstring(document.encode('utf-8'))
            xrd_dict = {}
            for xrd_elem in tree.findall('.//{http://www.w3.org/2005/01/xrd}link'):
                rel = xrd_elem.get('rel')
                href = xrd_elem.get('href')
                if rel and href:
                    xrd_dict[rel] = href
            return xrd_dict
        else:
            raise ValueError("Invalid webfinger document format")
    except (json.JSONDecodeError, ValueError, Exception) as e:
        raise ValueError("Failed to parse webfinger document") from e

