    Retrieve and parse a remote Diaspora webfinger document.

    :arg handle: Remote handle to retrieve
    :returns: dict
    """
    if not handle or not isinstance(handle, str):
        raise ValueError("Invalid handle provided")

    url = f"https://{handle}/.well-known/webfinger"
    headers = {
        'Accept': 'application/jrd+json',
        'User-Agent': 'Python Webfinger Client'
    }

    try:
        response = requests.get(url, headers=headers)
        response.raise_for_status()
        webfinger_data = response.json()
        return webfinger_data
    except requests.exceptions.RequestException as e:
        raise Exception(f"Failed to retrieve or parse webfinger document: {e}") from e

def retrieve_and_parse_diaspora_webfinger(handle):
    """
    Retrieve a and parse a remote Diaspora webfinger document.

    :arg handle: Remote handle to retrieve
    :returns: dict
    """
    if not handle.startswith('http') and not handle.startswith('https'):
        handle = f'https://{handle}'

    headers = {
        'Accept': 'application/jrd+json'
    }

    try:
        response = requests.get(handle, headers=headers, timeout=5)
        response.raise_for_status()
    except requests.RequestException as e:
        raise Exception(f"Failed to retrieve webfinger document: {e}")

    soup = BeautifulSoup(response.text, 'html.parser')
    jrd = soup.find('jrd')

    if not jrd:
        raise Exception("Invalid JRD document")

    parsed_data = {}
    for link in jrd.find_all('link'):
        rel = link.get('rel')
        if rel:
            parsed_data[rel] = link.get('href')

    return parsed_data

def retrieve_and_parse_diaspora_webfinger(handle):
    """
    Retrieve a and parse a remote Diaspora webfinger document.

    :arg handle: Remote handle to retrieve
    :returns: dict
    """

    if not handle or not isinstance(handle, str):
        raise ValueError("Invalid handle provided")

    url = f"https://{handle}/.well-known/webfinger?resource=acct:{handle}"

    try:
        response = requests.get(url)
        response.raise_for_status()
    except requests.exceptions.RequestException as e:
        raise Exception(f"Failed to retrieve webfinger document: {e}")

    try:
        root = ET.fromstring(response.content)
        webfinger_dict = {}

        for link in root.findall("{http://www.w3.org/2005/Atom}link"):
            rel = link.get("rel")
            href = link.get("href")

            if rel and href:
                webfinger_dict[rel] = href

        return webfinger_dict
    except ET.ParseError as e:
        raise Exception(f"Failed to parse webfinger document: {e}")

def send_document(url, data, timeout=10, method="post", *args, **kwargs):
    try:
        response = requests.request(method, url, data=data, timeout=timeout, *args, **kwargs)
        return response.status_code, None
    except requests.RequestException as e:
        return None, e

def dict_insert(dic, val, key, *keys):
    if not isinstance(dic, dict):
        raise TypeError("The first argument must be a dictionary")
    if not isinstance(key, str):
        raise TypeError("The third argument must be a string")
    if not all(isinstance(k, str) for k in keys):
        raise TypeError("All sub-key arguments must be strings")

    current_dict = dic
    keychain = [key] + list(keys)

    for k in keychain[:-1]:
        if k not in current_dict:
            current_dict[k] = {}
        current_dict = current_dict[k]

    current_dict[keychain[-1]] = val

