def dict_insert(dic, val, key, *keys):
    if not isinstance(dic, dict):
        raise ValueError("The first argument must be a dictionary")

    current_key = key
    sub_keys = list(keys)

    while sub_keys:
        if current_key not in dic:
            dic[current_key] = {}
        dic = dic[current_key]
        current_key = sub_keys.pop(0)

    dic[current_key] = val

def list_of_file_names(settings_dirs, spec_option):
    """Given a list of directory paths and a specification option, return a list of file names that match the specification.

    Args:
        settings_dirs (list of str): List of directory paths to search for files.
        spec_option (str): Specification option to filter file names.

    Returns:
        list of str: List of file names that match the specification.
    """
    if not isinstance(settings_dirs, list) or not all(isinstance(d, str) for d in settings_dirs):
        raise ValueError("settings_dirs must be a list of strings")
    if not isinstance(spec_option, str):
        raise ValueError("spec_option must be a string")

    matching_files = []
    for directory in settings_dirs:
        try:
            import os
            for filename in os.listdir(directory):
                if spec_option in filename:
                    matching_files.append(filename)
        except FileNotFoundError:
            print(f"Directory {directory} not found")
        except PermissionError:
            print(f"Permission denied for directory {directory}")

    return matching_files

