def _include_groups(self, parser_dict):
    """Resolves the include dict directive in the spec files. """
    if not isinstance(parser_dict, dict):
        raise ValueError("Invalid input: parser_dict must be a dictionary")

    if "include" not in parser_dict or not isinstance(parser_dict["include"], dict):
        return parser_dict

    include_dict = parser_dict["include"]
    for key, include_path in include_dict.items():
        if not isinstance(key, str) or not isinstance(include_path, str):
            raise ValueError("Invalid include dictionary: keys and values must be strings")

        try:
            with open(include_path, 'r') as file:
                include_content = file.read()
                include_dict[key] = include_content
        except FileNotFoundError:
            raise FileNotFoundError(f"Include file not found: {include_path}")
        except Exception as e:
            raise Exception(f"Error reading include file {include_path}: {e}")

    return parser_dict

def _include_groups(self, parser_dict):
    try:
        include_dict = parser_dict.get('include', {})
        groups = []
        for group_name, group_items in include_dict.items():
            if isinstance(group_items, list):
                groups.extend(group_items)
            else:
                raise ValueError(f"Invalid group items for group '{group_name}': {group_items}")
        return groups
    except Exception as e:
        raise RuntimeError(f"Error processing include groups: {e}")

def _include_groups(self, parser_dict):
    """Resolves the include dict directive in the spec files. """

    # Initialize an empty dictionary to hold the merged results
    merged_dict = {}

    # Check if the 'include' key exists in the parser_dict
    if 'include' in parser_dict:
        # Iterate through each item in the 'include' list
        for include_item in parser_dict['include']:
            # Check if the item is a dictionary
            if isinstance(include_item, dict):
                # Recursively call _include_groups to merge nested dictionaries
                merged_dict.update(self._include_groups(include_item))
            else:
                # Handle invalid include item type
                raise ValueError(f"Invalid include item type: {type(include_item)}")

    # Update the merged_dict with the rest of the parser_dict
    merged_dict.update(parser_dict)

    # Return the merged dictionary
    return merged_dict

def _include_groups(self, parser_dict):
    try:
        if 'include_dict' not in parser_dict:
            return parser_dict

        include_dict = parser_dict['include_dict']
        included_groups = {}

        for group_name, group_path in include_dict.items():
            try:
                with open(group_path, 'r') as file:
                    included_groups[group_name] = file.read()
            except FileNotFoundError:
                self.logger.warning(f"File not found: {group_path}")
            except Exception as e:
                self.logger.error(f"Error reading file {group_path}: {e}")

        parser_dict.update(included_groups)
        del parser_dict['include_dict']

    except Exception as e:
        self.logger.error(f"Error processing include_dict: {e}")

    return parser_dict

def _include_groups(self, parser_dict):
    """Resolves the include dict directive in the spec files. """
    try:
        include_dir = parser_dict.get('include_dir')
        if not include_dir:
            raise ValueError("include_dir is missing in parser_dict")

        for key, value in parser_dict.get('groups', {}).items():
            if isinstance(value, dict) and 'include' in value:
                include_file = value['include']
                full_path = f"{include_dir}/{include_file}"
                try:
                    with open(full_path, 'r') as file:
                        include_content = file.read()
                        value['content'] = include_content
                except FileNotFoundError:
                    raise FileNotFoundError(f"Include file not found: {full_path}")
                except Exception as e:
                    raise Exception(f"Error reading include file: {full_path}, error: {e}")

        return parser_dict
    except Exception as e:
        raise Exception(f"Error resolving include dict directive: {e}")

