def ansible_playbook(ir_workspace, ir_plugin, playbook_path, verbose=None,
                     extra_vars=None, ansible_args=None):
    """Wraps the 'ansible-playbook' CLI.

     :param ir_workspace: An Infrared Workspace object represents the active
     workspace
     :param ir_plugin: An InfraredPlugin object of the current plugin
     :param playbook_path: the playbook to invoke
     :param verbose: Ansible verbosity level
     :param extra_vars: dict. Passed to Ansible as extra-vars
     :param ansible_args: dict of ansible-playbook arguments to plumb down
         directly to Ansible.
    """
    try:
        command = ['ansible-playbook', playbook_path]

        if verbose:
            command.extend(['-v'] * verbose)

        if extra_vars:
            for key, value in extra_vars.items():
                command.extend(['--extra-vars', f'{key}={value}'])

        if ansible_args:
            command.extend(ansible_args)

        result = subprocess.run(command, check=True, stdout=subprocess.PIPE, stderr=subprocess.PIPE)
        return result.stdout.decode('utf-8')
    except subprocess.CalledProcessError as e:
        if e.stderr:
            return e.stderr.decode('utf-8')
        else:
            return e.output.decode('utf-8')
    except Exception as e:
        return f"An error occurred: {str(e)}"

def _run_playbook(cli_args: List[str], vars_dict: Dict[str, str], ir_workspace: Workspace, ir_plugin: Plugin) -> str:
    """Runs ansible cli with vars dict

    :param vars_dict: dict, Will be passed as Ansible extra-vars
    :param cli_args: the list of command line arguments
    :param ir_workspace: An Infrared Workspace object represents the active workspace
    :param ir_plugin: An InfraredPlugin object of the current plugin
    :return: ansible results
    """
    # Validate input
    if not cli_args or not isinstance(cli_args, list):
        raise ValueError("cli_args must be a non-empty list of strings")
    if not isinstance(vars_dict, dict):
        raise ValueError("vars_dict must be a dictionary")
    if not isinstance(ir_workspace, Workspace):
        raise ValueError("ir_workspace must be an instance of Workspace")
    if not isinstance(ir_plugin, Plugin):
        raise ValueError("ir_plugin must be an instance of Plugin")

    # Prepare ansible command
    ansible_cmd = ["ansible-playbook"] + cli_args
    ansible_cmd.extend(["-e", shlex.quote(str(vars_dict))])

    # Run ansible command
    try:
        result = subprocess.run(ansible_cmd, check=True, stdout=subprocess.PIPE, stderr=subprocess.PIPE, cwd=ir_workspace.path)
        return result.stdout.decode('utf-8')
    except subprocess.CalledProcessError as e:
        return f"Error running ansible: {e.stderr.decode('utf-8')}"

