    for root, _, files in os.walk(plugin_dir):
        for file in files:
            if file.endswith('.properties'):
                file_path = os.path.join(root, file)
                with open(file_path, 'r') as f:
                    for line in f:
                        line = line.strip()
                        if line and not line.startswith('#'):
                            key, value = line.split('=')
                            key = key.strip()
                            value = value.strip()
                            prop_dict[key] = value

    return prop_dict

